core_reasoning_2:
\section*{Claim}
Under the change of variables \(U=V^{1/n}\), the once-integrated traveling-wave equation
\[
V''+\frac{a}{b}V^{m/n}-\frac{g}{b}V^{1/n}=\frac{C}{2}
\]
implies the first-order separable equation
\[
V'^2=E+CV+B V^{1+1/n}-A V^{1+m/n},
\qquad
B=\frac{2ng}{(n+1)b},\quad A=\frac{2na}{(m+n)b}.
\]
Conversely, differentiating this first-order equation recovers the second-order oscillator equation wherever \(V'\ne0\), and hence everywhere by continuity when \(V\) is \(C^2\).

\section*{Premises}
\begin{align}
\text{(P1)}\quad &n>0,
\qquad m>0,
\qquad b\ne0,
\qquad V(\xi)>0
\quad\text{on the interval considered.}\\
\text{(P2)}\quad &V''+\frac{a}{b}V^{m/n}-\frac{g}{b}V^{1/n}=\frac{C}{2}.\\
\text{(P3)}\quad &\frac{d}{d\xi}\left(V'^2\right)=2V'V''.\\
\text{(P4)}\quad &\frac{d}{d\xi}\left(V^q\right)=qV^{q-1}V'
\quad\text{for each real exponent }q\text{ used below.}\\
\text{(P5)}\quad &\int C V'\,d\xi=CV+E_C,
\qquad
\int V^{1/n}V'\,d\xi=\frac{n}{n+1}V^{1+1/n}+E_B,\\
&\int V^{m/n}V'\,d\xi=\frac{n}{m+n}V^{1+m/n}+E_A.
\end{align}

\section*{Derivation}
Multiply (P2) by \(2V'\):
\begin{align}
2V'V''+\frac{2a}{b}V^{m/n}V'-\frac{2g}{b}V^{1/n}V'
&=CV' &&\text{by (P2)}.
\end{align}
Move all non-derivative terms to the right-hand side:
\begin{align}
2V'V''
&=CV'+\frac{2g}{b}V^{1/n}V'-\frac{2a}{b}V^{m/n}V'.
\end{align}
Integrate with respect to \(\xi\):
\begin{align}
V'^2
&=CV+\frac{2g}{b}\frac{n}{n+1}V^{1+1/n}
  -\frac{2a}{b}\frac{n}{m+n}V^{1+m/n}+E
  &&\text{by (P3)--(P5)}\\
&=E+CV+\frac{2ng}{(n+1)b}V^{1+1/n}
  -\frac{2na}{(m+n)b}V^{1+m/n}.
\end{align}
Define
\begin{align}
B&:=\frac{2ng}{(n+1)b},
& A&:=\frac{2na}{(m+n)b}.
\end{align}
Then
\begin{align}
V'^2&=E+CV+B V^{1+1/n}-A V^{1+m/n}.
\end{align}
Conversely, differentiate this first-order equation:
\begin{align}
2V'V''
&=CV'+B\left(1+\frac{1}{n}\right)V^{1/n}V'
  -A\left(1+\frac{m}{n}\right)V^{m/n}V' &&\text{by (P4)}\\
&=V'\left(C+\frac{2g}{b}V^{1/n}-\frac{2a}{b}V^{m/n}\right)
&&\text{substitute }A,B.
\end{align}
On any subinterval where \(V'\ne0\), division by \(2V'\) gives
\begin{align}
V''&=\frac{C}{2}+\frac{g}{b}V^{1/n}-\frac{a}{b}V^{m/n},\\
V''+\frac{a}{b}V^{m/n}-\frac{g}{b}V^{1/n}&=\frac{C}{2}.
\end{align}
If \(V\in C^2\), both sides are continuous, so the equality extends to points where \(V'=0\).

\section*{Final Result}
\[
\boxed{V'^2=E+CV+B V^{1+1/n}-A V^{1+m/n},\qquad
B=\frac{2ng}{(n+1)b},\quad A=\frac{2na}{(m+n)b}.}
\]
\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
Suppose a compacton profile has endpoint behavior
\[
U(\xi)\sim U_0(L-|\xi|)^p
\qquad (U_0\ne0,
\quad p\ne0)
\]
as \(\xi\to\pm L\). The weak \(K(m,n)\) cutoff conditions
\[
A_1(\pm L)=A_2(\pm L)=A_3(\pm L)=0
\]
are equivalent to the exponent condition
\[
p>\frac{2}{n}.
\]

\section*{Premises}
\begin{align}
\text{(P1)}\quad &s:=L-|\xi|,
\qquad s\to0^+\text{ as }\xi\to\pm L.\\
\text{(P2)}\quad &m,n>0,
\qquad a,b\ne0,
\qquad U_0\ne0,
\qquad p\ne0.\\
\text{(P3)}\quad &A_1:=bU^n,
\quad A_2:=b(U^n)',
\quad A_3:=-gU+aU^m+b(U^n)''.\\
\text{(P4)}\quad &A_1\sim bU_0^n s^{pn},
\qquad A_2\sim bpnU_0^n s^{pn-1}.\\
\text{(P5)}\quad &A_3\sim -gU_0^p s^p+aU_0^m s^{pm}+bpn(pn-1)U_0^n s^{pn-2}.\\
\text{(P6)}\quad &s^q\to0\text{ as }s\to0^+\quad\Longleftrightarrow\quad q>0.\\
\text{(P7)}\quad &A_1(\pm L)=A_2(\pm L)=A_3(\pm L)=0
\quad\Longleftrightarrow\quad A_1,A_2,A_3\to0\text{ as }s\to0^+.
\end{align}

\section*{Derivation}
From \(A_1\to0\), (P4) and (P6) give
\begin{align}
pn&>0. &&\text{from }A_1\sim bU_0^n s^{pn}
\end{align}
Since \(n>0\), this implies
\begin{align}
p&>0. &&\text{divide }pn>0\text{ by }n>0
\end{align}
From \(A_2\to0\), (P4) and (P6) give
\begin{align}
pn-1&>0,\\
pn&>1. &&\text{equivalent form}
\end{align}
Under \(p>0\), \(m>0\), and \(pn>1\), the first two terms in (P5) satisfy
\begin{align}
s^p&\to0,\\
s^{pm}&\to0. &&\text{by (P2) and (P6)}
\end{align}
Thus the remaining possible obstruction in \(A_3\) is the third term in (P5). Because \(pn>1\), its coefficient
\(bpn(pn-1)U_0^n\) is nonzero. Therefore, by (P5)--(P6),
\begin{align}
A_3\to0
&\Longleftrightarrow pn-2>0,\\
&\Longleftrightarrow pn>2,\\
&\Longleftrightarrow p>\frac{2}{n} &&\text{because }n>0.
\end{align}
The condition \(pn>2\) implies \(pn>1\) and \(pn>0\), so it also implies the conditions obtained from \(A_1\) and \(A_2\):
\begin{align}
p>\frac{2}{n}
&\Longrightarrow pn>2>1>0.
\end{align}
Hence the three endpoint conditions jointly hold exactly when \(p>2/n\).

\section*{Final Result}
\[
\boxed{A_1(\pm L)=A_2(\pm L)=A_3(\pm L)=0\quad\Longleftrightarrow\quad p>\frac{2}{n}.}
\]
\hfill$\blacksquare$
